import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { VulnerabilitiesIndexComponent } from 'app/components/vulnerabilities/vulnerabilities-index.component';
import { VulnerabilityUsersComponent } from 'app/components/vulnerabilities/users/vulnerability-users.component';
import { VulnerabilityFilesComponent } from 'app/components/vulnerabilities/files/vulnerability-files.component';
import { UserListGuard } from 'app/components/vulnerabilities/user-list-guard';

export const vulnerabilitiesRoutes: Routes = [
    {
        path: '',
        component: VulnerabilitiesIndexComponent,
        children: [
            {
                path: 'users',
                component: VulnerabilityUsersComponent,
                canActivate: [UserListGuard]
            },
            {
                path: 'files',
                component: VulnerabilityFilesComponent,
            },
            {
                path: '',
                redirectTo: 'users',
                pathMatch: 'full'
            },
        ],
    },
];

@NgModule({
    imports: [
        RouterModule.forChild(vulnerabilitiesRoutes)
    ],
    exports: [RouterModule],
    providers: [],
})
export class VulnerabilitiesRoutingModule { }
