import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import {
    VulnerabilitiesApi,
    VulnerabilitiesFileStatus,
    VulnerabilitiesItem,
} from '@imunify360-api/vulnerabilities';
import { take, tap, of, map, Observable } from 'rxjs';
import { AppState } from 'app/core/app.service';
import { VulnerabilityUsersApi, VulnerabilityUsersItem } from '@imunify360-api/vulnerability-users';


@Injectable()
export class VulnerabilitiesService {
    constructor(
        public xhr: XHR,
        public appState: AppState
    ) {}



    get = this.xhr.wrap(this.xhr.rx(VulnerabilitiesApi.list), VulnerabilitiesItem);
    getUsers = this.xhr.wrap(this.xhr.rx(VulnerabilityUsersApi.list), VulnerabilityUsersItem);

    applyPatch = this.xhr.rx(VulnerabilitiesApi.applyPatch);

    revertPatch = this.xhr.rx(VulnerabilitiesApi.revertPatch);

    getPurchaseUrl(): Observable<string | null> {
        if (this.appState.imunifyPatchPurchaseUrl !== undefined){
            return of(this.appState.imunifyPatchPurchaseUrl);
        }

        return this.get({
            by_status: [VulnerabilitiesFileStatus.vulnerable],
            limit: 1,
        }).pipe(
            take(1),
            map(result => {
                const item = result?.data?.items;
                return item[item.length-1]?.purchaseUrl || null;
            }),
            tap(url => {
                if (url) {
                   this.appState.imunifyPatchPurchaseUrl = url;
                }
                return url ?? null
            })
        );
    }

}
