import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, Router,
    RouterStateSnapshot, UrlTree } from '@angular/router';
import { AuthState } from 'app/services/auth-state';
import { LicenseState } from 'app/services/license-state';


@Injectable()
export class UserListGuard implements CanActivate {
    constructor(
        private router: Router,
        private authState: AuthState,
        private licenseState: LicenseState,
    ) {}

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
        if (this.licenseState.license.value.isSingleUser() || !this.authState.isAdmin.value) {
            this.router.navigate(['/', IMUNIFY_PACKAGE, this.authState.role.value, 'vulnerabilities', 'files']);
            return false;
        }

        return true;
    }
}
