import { ChangeDetectorRef, Component, OnDestroy } from '@angular/core';
import { AuthState } from 'app/services/auth-state';
import { LicenseState } from 'app/services/license-state';
import { Subject, take, map, combineLatest, takeUntil, Observable } from 'rxjs';
import { VulnerabilitiesService } from 'app/services/vulnerabilities';


@Component({
    selector: 'vulnerabilities-root',
    templateUrl: './vulnerabilities-index.component.html',
    styleUrls: ['./vulnerabilities-index.component.scss'],
})
export class VulnerabilitiesIndexComponent implements OnDestroy {
    private destroy$ = new Subject<void>();
    showMultiUserTabs$: Observable<boolean>;

    purchaseUrl: string | null;

    constructor(
        public authState: AuthState,
        public licenseState: LicenseState,
        private cdr: ChangeDetectorRef,
        public vulnerabilitiesService: VulnerabilitiesService,
    ) {
        this.showMultiUserTabs$ = combineLatest([
            this.authState.isAdmin,
            this.licenseState.license,
        ]).pipe(
            takeUntil(this.destroy$),
            map(([isAdmin, license]) => {
                return isAdmin && (license?.user_count || 0) > 1;
            }),
        );

        this.vulnerabilitiesService.getPurchaseUrl().pipe(take(1)).subscribe(purchaseUrl => {
            this.purchaseUrl = purchaseUrl;
            this.cdr.markForCheck();
        });
    }

    ngOnDestroy(): void {
        this.destroy$.next();
        this.destroy$.complete();
    }
}
